const imageBlobUrls = new Map();
const imageBlobs = new Map();
window._carSoccerImageBlobs = imageBlobs;
window._carSoccerImageBlobUrls = imageBlobUrls;

for (const [path, dataUri] of Object.entries(window.IMAGES_MAP)) {
  const commaIdx = dataUri.indexOf(',');
  const mime = dataUri.substring(5, dataUri.indexOf(';'));
  const binStr = atob(dataUri.substring(commaIdx + 1));
  const len = binStr.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binStr.charCodeAt(i);
  const blob = new Blob([bytes], { type: mime });
  const blobUrl = URL.createObjectURL(blob);
  imageBlobs.set(path, blob);
  imageBlobUrls.set(path, blobUrl);
}

const origSrcDesc = Object.getOwnPropertyDescriptor(HTMLImageElement.prototype, 'src');
Object.defineProperty(HTMLImageElement.prototype, 'src', {
  set(val) {
    if (typeof val === 'string') {
      let cleanPath = val;
      try {
        const u = new URL(val, document.baseURI);
        cleanPath = u.pathname;
      } catch {}
      for (const [path, bUrl] of imageBlobUrls.entries()) {
        if (cleanPath === path || cleanPath.endsWith(path) || val.includes(path)) {
          return origSrcDesc.set.call(this, bUrl);
        }
      }
    }
    return origSrcDesc.set.call(this, val);
  },
  get() {
    return origSrcDesc.get.call(this);
  }
});
